import { defineConfig, devices } from "@playwright/test";

/**
 * E2E config for the browser-level checks in `tests/` (currently the Svelte
 * client-island hydration guard).
 *
 * `webServer` boots `wrangler dev` against the built Worker and assets
 * (dist/server/wrangler.json is generated by the Cloudflare adapter at build
 * time), so the tests run against the real production runtime — including the
 * on-demand dashboard SPA fallback. A build must already exist (`npm run
 * build` in CI, or `npm run build:local` locally). Locally an already-running
 * server on the port is reused; CI always starts a fresh one. (`astro
 * preview` is unusable here: with the adapter it daemonizes and returns
 * immediately.)
 */
const PORT = 4321;
const BASE_URL = `http://localhost:${PORT}`;

export default defineConfig({
  testDir: "./tests",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? "github" : "list",
  use: {
    baseURL: BASE_URL,
    trace: "on-first-retry",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: {
    command: `npx wrangler dev --config dist/server/wrangler.json --port ${PORT}`,
    url: BASE_URL,
    reuseExistingServer: !process.env.CI,
    timeout: 120_000,
  },
});
